def has = { String n -> binding.hasVariable(n) && binding.getVariable(n) != null }
def get = { String n -> has(n) ? binding.getVariable(n) : null }
def text = { String n -> def v = get(n); (v == null) ? '' : v.toString().trim() }
def s = text('search')
def modeIn = text('mode')
def rawFilter = get('filter')
def rawSort = get('sort')
def rawLimit = get('limit')
def rawOffset = get('offset')

// Every problem is collected and the request refused with all of them named.
def problems = []
def MODES = ['Rate', 'PctOfTarget']
String modeSel = ''
if (!modeIn.isEmpty()) {
    def hit = MODES.find { it.equalsIgnoreCase(modeIn) }
    if (hit == null) problems << ('mode must be Rate or PctOfTarget, got "' + modeIn + '"')
    else modeSel = hit
}

// The fields a caller may filter or sort by, and their kinds. bandCount and usedBy are
// computed, which is the other reason the contract is evaluated in memory.
def FIELDS = [name: 'TEXT', rateTableId: 'TEXT', mode: 'TEXT', tiering: 'TEXT', unitType: 'TEXT', bandCount: 'NUMBER', usedBy: 'NUMBER', version: 'NUMBER']
def TEXT_OPS = ['EQUAL','NOT_EQUAL','ICONTAINS','NOT_ICONTAINS','CONTAINS','NOT_CONTAINS','STARTS_WITH','NOT_STARTS_WITH','ENDS_WITH','NOT_ENDS_WITH','EXISTS','MISSING','REGEX','NOT_REGEX','IN','NOT_IN'] as Set
def NUM_OPS = ['EQUAL','NOT_EQUAL','LT','LTE','GT','GTE','BETWEEN','EXISTS','MISSING','IN','NOT_IN'] as Set
def NO_VALUE = ['EXISTS','MISSING'] as Set
def GROUP_OPS = ['AND','OR'] as Set
def toNum = { String v, String where ->
    if (v ==~ /^-?\d{1,12}(\.\d{1,6})?$/) return new BigDecimal(v)
    problems << (where + ': needs a number, got "' + v + '"'); return null
}

int leafCount = 0
def norm
norm = { node, String path ->
    if (!(node instanceof Map)) { problems << (path + ': a filter node must be an object'); return null }
    def op = (node.op == null) ? '' : String.valueOf(node.op).trim().toUpperCase()
    def field = (node.field == null) ? '' : String.valueOf(node.field).trim()
    if (field.isEmpty()) {
        if (!GROUP_OPS.contains(op)) { problems << (path + ': a group needs op AND or OR, got "' + op + '"'); return null }
        def vals = node.values
        if (vals != null && !(vals instanceof List)) { problems << (path + ': values of a group must be a list'); return null }
        def kids = []
        (vals ?: []).eachWithIndex { child, i -> def c = norm(child, path + '.values[' + i + ']'); if (c != null) kids << c }
        if (kids.isEmpty()) return null
        return [group: op, kids: kids]
    }
    def kind = FIELDS[field]
    if (kind == null) { problems << (path + ': unknown field "' + field + '"'); return null }
    if (!(kind == 'NUMBER' ? NUM_OPS : TEXT_OPS).contains(op)) { problems << (path + ': operator "' + op + '" is not valid for ' + field); return null }
    def list = []
    def vals = node.values
    if (vals instanceof List) { vals.each { v -> if (v instanceof List) { v.each { if (it != null) list << it } } else if (v != null) list << v } }
    else if (vals != null) list << vals
    def strs = list.collect { String.valueOf(it).trim() }
    if (NO_VALUE.contains(op)) strs = []
    else if (op == 'BETWEEN') { if (strs.size() != 2) { problems << (path + ': BETWEEN needs exactly two values'); return null } }
    else if (op == 'IN' || op == 'NOT_IN') { strs = strs.findAll { !it.isEmpty() }; if (strs.isEmpty()) { problems << (path + ': ' + op + ' needs at least one value'); return null } }
    else if (strs.size() != 1 || strs[0].isEmpty()) { problems << (path + ': ' + op + ' needs one value'); return null }
    def nums = []
    if (kind == 'NUMBER') {
        strs.each { v -> def n = toNum(v, path); if (n != null) nums << n }
        if (nums.size() != strs.size()) return null
    }
    if (op == 'REGEX' || op == 'NOT_REGEX') {
        try { java.util.regex.Pattern.compile(strs[0]) } catch (Exception e) { problems << (path + ': not a valid regular expression: ' + strs[0]); return null }
    }
    leafCount++
    return [field: field, op: op, kind: kind, text: strs, nums: nums]
}

def filterIn = rawFilter
if (filterIn instanceof String) {
    def t = filterIn.trim()
    if (t.isEmpty()) filterIn = null
    else { try { filterIn = new groovy.json.JsonSlurper().parseText(t) } catch (Exception e) { problems << ('filter is not valid JSON: ' + e.getMessage()); filterIn = null } }
}
if (filterIn instanceof Map && filterIn.isEmpty()) filterIn = null
def tree = (filterIn == null) ? null : norm(filterIn, 'filter')
if (tree == null) tree = [group: 'AND', kids: []]

def sortIn = rawSort
if (sortIn instanceof String) {
    def t = sortIn.trim()
    if (t.isEmpty()) sortIn = null
    else { try { sortIn = new groovy.json.JsonSlurper().parseText(t) } catch (Exception e) { problems << ('sort is not valid JSON: ' + e.getMessage()); sortIn = null } }
}
if (sortIn instanceof Map) sortIn = [sortIn]
if (sortIn != null && !(sortIn instanceof List)) { problems << 'sort must be a list of {field, order}'; sortIn = null }
def sorts = []
if (sortIn != null) sortIn.eachWithIndex { sv, i ->
    if (!(sv instanceof Map)) { problems << ('sort[' + i + '] must be an object'); return }
    def f = (sv.field == null) ? '' : String.valueOf(sv.field).trim()
    def o = (sv.order == null) ? 'ASC' : String.valueOf(sv.order).trim().toUpperCase()
    if (FIELDS[f] == null) { problems << ('sort[' + i + ']: unknown field "' + f + '"'); return }
    if (o != 'ASC' && o != 'DESC') { problems << ('sort[' + i + ']: order must be ASC or DESC, got "' + o + '"'); return }
    sorts << [field: f, order: o, kind: FIELDS[f]]
}

def toInt = { v, String name, int dflt ->
    if (v == null) return dflt
    if (v instanceof Number) return ((Number) v).intValue()
    def t = v.toString().trim()
    if (t.isEmpty()) return dflt
    if (t ==~ /^\d{1,9}$/) return Integer.parseInt(t)
    problems << (name + ' must be a whole number, got: ' + t)
    return dflt
}
int pl = toInt(rawLimit, 'limit', 50)
if (pl < 1) pl = 1
if (pl > 500) pl = 500
int po = toInt(rawOffset, 'offset', 0)
if (po < 0) po = 0

return [valid: problems.isEmpty(), reason: problems.join('; '), search: s, modeSel: modeSel,
        filter: tree, filterCount: leafCount, sorts: sorts, pageLimit: pl, pageOffset: po]

def ids = []
if (rows != null) rows.each { r -> ids << String.valueOf(r.id) }
// '__none__' keeps an empty result a clean no-op instead of an unfiltered scan.
def useIds = ids.isEmpty() ? ['__none__'] : ids
return [count: ids.size(),
        childFilter: [operator: 'AND', filters: [[property: 'properties.rateTableId', filter: [operator: 'IN', value: useIds]]]]]

def OPEN = 2147483647L
def asLong = { v -> (v == null) ? null : Long.valueOf(String.valueOf(v)) }

// Bands and component usage, grouped by the parent record id - one pass each.
def bandsOf = [:]
if (bandRows != null) bandRows.each { b ->
    def k = String.valueOf(b.properties?.rateTableId)
    if (!bandsOf.containsKey(k)) bandsOf[k] = []
    bandsOf[k] << b.properties
}
def usedOf = [:]
if (compRows != null) compRows.each { c ->
    def k = String.valueOf(c.properties?.rateTableId)
    usedOf[k] = (usedOf[k] ?: 0) + 1
}

def tables = []
if (rows != null) rows.each { r ->
    def p = r.properties ?: [:]
    def id = String.valueOf(r.id)
    def bands = bandsOf[id] ?: []
    Long lo = null; Long hi = null
    bands.each { b -> def f = asLong(b.fromPct); def t = asLong(b.toPct)
        if (f != null && (lo == null || f < lo)) lo = f
        if (t != null && (hi == null || t > hi)) hi = t }
    // Tables written before v3 have no unit type or version info: they are Percent,
    // version 1, with no effective dates (0 = not set / End of Time).
    tables << [id: id, rateTableId: String.valueOf(p.rateTableId ?: ''), name: String.valueOf(p.name ?: ''),
               mode: String.valueOf(p.mode ?: ''), tiering: String.valueOf(p.tiering ?: ''), unitType: String.valueOf(p.unitType ?: 'Percent'),
               version: (asLong(p.version) ?: 1L), effectiveStart: (asLong(p.effectiveStart) ?: 0L), effectiveEnd: (asLong(p.effectiveEnd) ?: 0L),
               bandCount: bands.size(), fromPct: (lo == null) ? 0L : lo, toPct: (hi == null) ? 0L : hi,
               openEnded: (hi != null && hi == OPEN), usedBy: (usedOf[id] ?: 0)]
}

// The tree n_Norm normalised: a group {group, kids} or a leaf {field, op, kind, text, nums}.
def tree = (binding.hasVariable('filter') && filter != null) ? filter : [group: 'AND', kids: []]
def sortList = (binding.hasVariable('sorts') && sorts != null) ? sorts : []
def q = (search == null) ? '' : search.toString().trim().toLowerCase()
def modeWanted = (modeSel == null) ? '' : modeSel.toString()
boolean hasFilter = !(tree.group != null && (tree.kids == null || tree.kids.isEmpty()))

// Every operator is spelled out; there is deliberately no default branch, because an
// operator nobody recognised must never evaluate to true. n_Norm already refused the rest.
def evalLeaf = { r, f ->
    if (f.kind == 'NUMBER') {
        def v = r[f.field]
        if (v == null) return f.op == 'MISSING'
        BigDecimal x = new BigDecimal(String.valueOf(v))
        def nums = f.nums.collect { new BigDecimal(String.valueOf(it)) }
        if (f.op == 'EXISTS') return true
        if (f.op == 'MISSING') return false
        if (f.op == 'EQUAL') return x.compareTo(nums[0]) == 0
        if (f.op == 'NOT_EQUAL') return x.compareTo(nums[0]) != 0
        if (f.op == 'LT') return x.compareTo(nums[0]) < 0
        if (f.op == 'LTE') return x.compareTo(nums[0]) <= 0
        if (f.op == 'GT') return x.compareTo(nums[0]) > 0
        if (f.op == 'GTE') return x.compareTo(nums[0]) >= 0
        if (f.op == 'BETWEEN') { def lo = nums[0].min(nums[1]); def hi = nums[0].max(nums[1]); return x.compareTo(lo) >= 0 && x.compareTo(hi) <= 0 }
        if (f.op == 'IN') return nums.any { it.compareTo(x) == 0 }
        if (f.op == 'NOT_IN') return !nums.any { it.compareTo(x) == 0 }
        return false
    }
    def raw = String.valueOf(r[f.field] == null ? '' : r[f.field])
    def needle = f.text.isEmpty() ? '' : String.valueOf(f.text[0])
    if (f.op == 'EXISTS') return !raw.isEmpty()
    if (f.op == 'MISSING') return raw.isEmpty()
    if (f.op == 'EQUAL') return raw == needle
    if (f.op == 'NOT_EQUAL') return raw != needle
    if (f.op == 'ICONTAINS') return raw.toLowerCase().contains(needle.toLowerCase())
    if (f.op == 'NOT_ICONTAINS') return !raw.toLowerCase().contains(needle.toLowerCase())
    if (f.op == 'CONTAINS') return raw.contains(needle)
    if (f.op == 'NOT_CONTAINS') return !raw.contains(needle)
    if (f.op == 'STARTS_WITH') return raw.startsWith(needle)
    if (f.op == 'NOT_STARTS_WITH') return !raw.startsWith(needle)
    if (f.op == 'ENDS_WITH') return raw.endsWith(needle)
    if (f.op == 'NOT_ENDS_WITH') return !raw.endsWith(needle)
    if (f.op == 'REGEX') return java.util.regex.Pattern.compile(needle).matcher(raw).find()
    if (f.op == 'NOT_REGEX') return !java.util.regex.Pattern.compile(needle).matcher(raw).find()
    if (f.op == 'IN') return f.text.any { String.valueOf(it) == raw }
    if (f.op == 'NOT_IN') return !f.text.any { String.valueOf(it) == raw }
    return false
}
def evalNode
evalNode = { r, n ->
    if (n.group != null) {
        if (n.kids == null || n.kids.isEmpty()) return true
        if (n.group == 'OR') return n.kids.any { k -> evalNode(r, k) }
        return n.kids.every { k -> evalNode(r, k) }
    }
    return evalLeaf(r, n)
}
// Search means what it means on the platform: case-insensitive contains, OR across the
// searchable fields, ANDed with the filter and the mode shortcut.
def SEARCH_FIELDS = ['name', 'rateTableId']
def matches = { r ->
    if (!modeWanted.isEmpty() && String.valueOf(r.mode) != modeWanted) return false
    if (!q.isEmpty() && !SEARCH_FIELDS.any { fld -> String.valueOf(r[fld] == null ? '' : r[fld]).toLowerCase().contains(q) }) return false
    return evalNode(r, tree)
}
boolean filtering = !q.isEmpty() || hasFilter || !modeWanted.isEmpty()
def visible = filtering ? tables.findAll { r -> matches(r) } : tables

// Default order is by name, so two calls with no sort agree; an explicit sort replaces it.
if (sortList.isEmpty()) {
    visible = visible.sort { a, b -> String.valueOf(a.name).compareToIgnoreCase(String.valueOf(b.name)) }
} else {
    visible = visible.sort { a, b ->
        for (s in sortList) {
            int c = 0
            if (s.kind == 'NUMBER') c = new BigDecimal(String.valueOf(a[s.field] ?: 0)).compareTo(new BigDecimal(String.valueOf(b[s.field] ?: 0)))
            else c = String.valueOf(a[s.field] == null ? '' : a[s.field]).compareToIgnoreCase(String.valueOf(b[s.field] == null ? '' : b[s.field]))
            if (c != 0) return (s.order == 'DESC') ? -c : c
        }
        return 0
    }
}

int total = visible.size()
int from = (pageOffset > total) ? total : pageOffset
int to = ((from + pageLimit) > total) ? total : (from + pageLimit)
def page = (total == 0) ? [] : new ArrayList(visible.subList(from, to))

// A bulk fetch that hit its limit lies by omission - say so.
int gotT = (rows == null) ? 0 : rows.size(); int totT = (rowsTotal == null) ? gotT : Integer.valueOf(String.valueOf(rowsTotal))
int gotB = (bandRows == null) ? 0 : bandRows.size(); int totB = (bandsTotal == null) ? gotB : Integer.valueOf(String.valueOf(bandsTotal))
int gotC = (compRows == null) ? 0 : compRows.size(); int totC = (compsTotal == null) ? gotC : Integer.valueOf(String.valueOf(compsTotal))
boolean truncated = gotT < totT || gotB < totB || gotC < totC

return [rows: page, total: total, hasMore: to < total, truncated: truncated,
        message: page.size() + ' rate table(s)' + (filtering ? (' of ' + total + ' matching') : '') + (truncated ? ' (set truncated - narrow the query)' : '')]
